import * as U from '../ui.js';
let id=new URLSearchParams(location.search).get('id')||U.db.courses[0]?.id;
U.mount(()=>{let c=U.course(id);if(!c)return U.heading('My courses','Course not found.','Choose a course from My courses.','<a class="btn" href="courses.html">My courses →</a>');let a=U.attendanceStats(id),sessions=U.db.class_sessions.filter(s=>s.course_id===id&&U.day(s.starts_at)>=U.TODAY&&s.status!=='cancelled').slice(0,4),tasks=U.db.tasks.filter(t=>t.course_id===id);return U.heading(c.course_code,c.name,c.semester,U.button('Add task','tasks','',{course_id:id}))+`<div class="cards">${U.stat('Attendance',a.percent===null?'—':a.percent+'%','Minimum '+c.minimum_attendance_percent+'%','check')}${U.stat('Open tasks',tasks.filter(t=>!['done','cancelled'].includes(t.status)).length,'Assignments, exams, and study','tasks')}${U.stat('Classes attended',a.present+' <span>/ '+a.total+'</span>','Based on marked, completed sessions','calendar')}${U.stat('Unmarked classes',a.unmarked,'Keep your attendance up to date','info')}</div><div class="dashboard-grid"><div class="stack">${U.section('Upcoming classes',sessions.map(U.sessionRow).join('')||U.empty('No upcoming classes.'),'<a href="schedule.html" class="text-link">Full schedule →</a>')}${U.section('Course tasks',tasks.map(U.taskRow).join('')||U.empty('No tasks for this course.'))}</div><div class="stack">${U.section('Your professor',`<div class="course-symbol">${U.icon('study')}</div><h3>${U.esc(c.professor_name||'Not set')}</h3><p class="small muted" style="margin:12px 0">${U.esc(c.professor_email||'No contact email')}</p>${c.professor_email?`<a class="text-link" href="mailto:${U.esc(c.professor_email)}">Email professor →</a>`:''}`)}${U.section('Course settings',`<p class="small muted" style="line-height:1.9">Semester: ${U.date(c.semester_start)} – ${U.date(c.semester_end)}<br>Minimum attendance: ${c.minimum_attendance_percent}%<br>Late counts as present: ${c.late_counts_as_present?'Yes':'No'}<br>Excused absences excluded: ${c.exclude_excused_from_percentage?'Yes':'No'}</p><div style="margin-top:18px">${U.button('Edit course','courses',c.id)}</div>`)}<a class="btn" href="attendance.html?course=${id}">View attendance history →</a></div></div>`});
